#include "stdafx.h"#include "HcdElementBase.h"struct SFRCP_P{#include "PrivateVars/FRCP.h"};class KFRCP : public KHcdElementBase  , protected SFRCP_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );};static KHcdFactory _FRCP("FRCP", KFRCP::Create);IHcdElement *KFRCP::Create(){  return new KFRCP;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KFRCP, 4 )void KFRCP::InitParm(){#include "PrivateVars/FRCP.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KFRCP::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}